<template>
  <AuthLayout :loading="processing" :showInfoPanel="false">
    <AuthCard
      :title="$t('mfa_challenge_title')"
      :subtitle="subtitle"
      :error="errorMessage ? errorMessage : ''"
      :dismissible-error="true"
      @dismiss-error="errorMessage = ''"
    >
      <q-form @submit.prevent="onSubmit">
        <q-input
          v-model="code"
          :label="codeLabel"
          :mask="useBackup ? '' : '######'"
          inputmode="numeric"
          autofocus
          outlined
          :disable="processing"
          data-test="mfa-challenge-code-input"
          class="q-mb-md"
        />
        <q-checkbox
          v-model="rememberDevice"
          :label="$t('mfa_challenge_remember_device')"
          :disable="processing"
          dense
          data-test="mfa-challenge-remember-device"
          class="q-mb-md"
        />
      </q-form>

      <!-- AuthCard owns the `actions` slot. While this sat inside <q-form> it
           was a named slot on QForm, which renders only its default slot, so
           the button never appeared and the code could be submitted by
           pressing Enter alone (DOCB-13847). Outside the form element
           type="submit" no longer reaches it, so the click handler submits —
           the same shape Login.vue uses. -->
      <template #actions>
        <q-btn
          unelevated
          type="submit"
          color="primary"
          text-color="white"
          :disable="!code || processing"
          :label="$t('mfa_challenge_submit')"
          class="auth-submit-btn"
          data-test="mfa-challenge-submit-button"
          @click="onSubmit()"
        />
      </template>
    </AuthCard>

    <template #footer>
      <a
        v-if="hasWebauthn"
        class="text-primary cursor-pointer hover:underline text-sm"
        data-test="mfa-challenge-use-passkey"
        @click="usePasskey()"
      >
        {{ $t('mfa_challenge_use_passkey') }}
      </a>
      <a
        v-if="hasEmail && !useEmail"
        class="text-primary cursor-pointer hover:underline text-sm q-ml-md"
        data-test="mfa-challenge-use-email"
        @click="switchToEmail()"
      >
        {{ $t('mfa_challenge_use_email') }}
      </a>
      <a
        v-if="useEmail"
        class="text-primary cursor-pointer hover:underline text-sm"
        data-test="mfa-challenge-resend-email"
        @click="switchToEmail()"
      >
        {{ $t('mfa_challenge_resend_email') }}
      </a>
      <a
        v-if="hasTotp && (useEmail || useBackup)"
        class="text-primary cursor-pointer hover:underline text-sm q-ml-md"
        data-test="mfa-challenge-use-authenticator"
        @click="switchToAuthenticator()"
      >
        {{ $t('mfa_challenge_use_authenticator') }}
      </a>
      <a
        v-if="hasBackup && !useBackup"
        class="text-primary cursor-pointer hover:underline text-sm q-ml-md"
        data-test="mfa-challenge-toggle-backup"
        @click="toggleBackup()"
      >
        {{ $t('mfa_challenge_use_backup') }}
      </a>
      <a
        class="text-primary cursor-pointer hover:underline text-sm q-ml-md"
        data-test="mfa-challenge-other-account-link"
        @click="onUseOtherAccount()"
      >
        {{ $t('org_picker_other_account') }}
      </a>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { AuthLayout, AuthCard } from 'src/components/Auth';
import { LocalStorage, SessionStorage } from 'quasar';
import { useAuthTokenStore } from 'src/store/main';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { AppVersion } from 'src/utils/app_version';
import { takeMfaPending, type MfaPending } from 'src/utils/mfa/mfa-pending';
import { performAuthentication, isWebAuthnSupported } from 'src/utils/mfa/webauthn';
import {
  isOrgSelectionRequired,
  storeOrgSelectionPending,
} from 'src/utils/organization/org-selection-pending';
import type { dynamicObj } from 'src/pages/assets';

// MFA login step 2 (DOCB-13743): the auth service withheld the full token in
// step 1 (mfa_required) — this screen takes the single-use mfa_token + the
// second-factor code and completes the login via POST /v2/mfa/verify/{totp,backup}.
// On success the auth service resumes the login flow, so the response is either
// a full token pair OR an org_selection payload (chained to /select-organisation),
// mirroring OrgPicker.vue's token-storage + navigation.
export default defineComponent({
  name: 'MfaChallenge',
  components: { AuthLayout, AuthCard },
  data() {
    return {
      pending: null as MfaPending | null,
      code: '' as string,
      useBackup: false,
      useEmail: false,
      rememberDevice: false,
      processing: false,
      errorMessage: '',
    };
  },
  computed: {
    hasBackup(): boolean {
      return !!this.pending?.methods?.includes('backup');
    },
    hasEmail(): boolean {
      return !!this.pending?.methods?.includes('email');
    },
    hasTotp(): boolean {
      return !!this.pending?.methods?.includes('totp');
    },
    hasWebauthn(): boolean {
      return !!this.pending?.methods?.includes('webauthn') && isWebAuthnSupported();
    },
    subtitle(): string {
      if (this.useBackup) return this.$t('mfa_challenge_backup_subtitle') as string;
      if (this.useEmail) return this.$t('mfa_challenge_email_subtitle') as string;
      return this.$t('mfa_challenge_subtitle') as string;
    },
    codeLabel(): string {
      if (this.useBackup) return this.$t('mfa_challenge_backup_label') as string;
      return this.$t('mfa_challenge_code_label') as string;
    },
  },
  mounted() {
    this.pending = takeMfaPending();
    if (!this.pending || !this.pending.mfaToken) {
      // Direct navigation without a pending challenge (refresh, bookmark, or
      // the mfa_token already expired) — nothing to verify against.
      this.$router.replace('/login');
      return;
    }
    // Email as the only factor: nothing to type from an app, so send the code
    // straight away and start in email mode (DOCB-13744).
    if (this.hasEmail && !this.hasTotp) {
      void this.switchToEmail();
    }
  },
  methods: {
    toggleBackup() {
      this.useBackup = !this.useBackup;
      if (this.useBackup) this.useEmail = false;
      this.code = '';
      this.errorMessage = '';
    },
    switchToAuthenticator() {
      this.useBackup = false;
      this.useEmail = false;
      this.code = '';
      this.errorMessage = '';
    },
    // DOCB-13744: request (or resend) a login-time email OTP, then switch the
    // form into email mode. The mfa_token is re-usable across sends within the
    // challenge lifetime; the server throttles resends (429 cooldown).
    async switchToEmail() {
      if (!this.pending || this.processing) return;
      this.processing = true;
      this.errorMessage = '';
      try {
        await userApiService.sendMfaEmail(this.pending.mfaToken, this.pending.authRegion);
        this.useEmail = true;
        this.useBackup = false;
        this.code = '';
      } catch (err) {
        this.errorMessage = this.serverErrorMessage(err);
      } finally {
        this.processing = false;
      }
    },
    onUseOtherAccount() {
      this.$router.replace('/login');
    },
    // DOCB-13847: ApiExceptions.getErrorMessage() expects the axios RESPONSE, not
    // the axios error. Handed the error, it finds no `error_code` at the top
    // level, skips the Tolgee lookup entirely and falls back to axios' own
    // "Request failed with status code 400" — which is what users saw when a
    // passkey challenge was rejected. Login.vue passes `error.response` for this
    // reason; every catch on this page now goes through here so the two pages
    // cannot drift apart again. Falls back to the error itself so a transport
    // failure (no response) still produces a message.
    serverErrorMessage(err: unknown): string {
      const response = (err as { response?: unknown } | undefined)?.response;
      const msg = ApiExceptions.getErrorMessage((response ?? err) as dynamicObj);
      return (msg as string) || (this.$t('mfa_challenge_error') as string);
    },
    async onSubmit() {
      if (!this.code || !this.pending) return;
      this.processing = true;
      this.errorMessage = '';
      // The mfa_token is single-use per successful verify but re-usable across
      // failed attempts (server bounds attempts per challenge), so keep the
      // pending in a local var — takeMfaPending() already cleared storage.
      const pending = this.pending;
      try {
        let verify = userApiService.verifyMfaTotp;
        if (this.useBackup) verify = userApiService.verifyMfaBackup;
        else if (this.useEmail) verify = userApiService.verifyMfaEmail;
        const response = await verify.call(
          userApiService,
          pending.mfaToken,
          this.code.trim(),
          pending.authRegion,
          this.rememberDevice,
        );

        await this.handleVerifyResponse(response, pending);
      } catch (err) {
        // Wrong/replayed code, too many attempts (429), or an expired mfa_token
        // (restart login). Keep the pending token in SessionStorage so the user
        // can retry within the challenge's lifetime.
        SessionStorage.set('mfa_pending', pending);
        this.errorMessage = this.serverErrorMessage(err);
      } finally {
        this.processing = false;
      }
    },
    // The auth service resumed the login after a verified factor: >1 org with no
    // default ⇒ hand off to the org picker (step 3), else store the token pair.
    // Shared by the code-entry (onSubmit) and passkey (usePasskey) flows.
    async handleVerifyResponse(response: dynamicObj, pending: MfaPending) {
      if (isOrgSelectionRequired(response)) {
        storeOrgSelectionPending({
          selectionToken: response.selection_token,
          organisations: response.organisations,
          redirect: pending.redirect,
          forceFullReload: pending.forceFullReload,
        });
        this.$router.push('/select-organisation');
        return;
      }
      await this.finishWithToken(response, pending);
    },
    // DOCB-13745: passkey login. Must run from a user gesture (this click), so it
    // is never auto-triggered. Fetches get() options, runs the WebAuthn ceremony,
    // then verifies — resuming login exactly like a code verify.
    async usePasskey() {
      if (!this.pending || this.processing) return;
      this.processing = true;
      this.errorMessage = '';
      const pending = this.pending;
      try {
        const options = await userApiService.webauthnChallenge(
          pending.mfaToken,
          pending.authRegion,
        );
        const assertion = await performAuthentication(options);
        const response = await userApiService.webauthnVerify(
          pending.mfaToken,
          assertion,
          pending.authRegion,
          this.rememberDevice,
        );
        await this.handleVerifyResponse(response, pending);
      } catch (err) {
        SessionStorage.set('mfa_pending', pending);
        // Passkey ceremony errors carry a friendly i18n code — prefer it over
        // the raw WebAuthn/w3.org DOMException text.
        const code = (err as { code?: string })?.code;
        if (code && typeof code === 'string' && code.startsWith('mfa_passkey_error_')) {
          this.errorMessage = this.$t(code) as string;
        } else {
          this.errorMessage = this.serverErrorMessage(err);
        }
      } finally {
        this.processing = false;
      }
    },
    // Same token-storage + navigation as OrgPicker.vue#onSubmit: the WRITES are
    // guarded by the 'docbits-token-refresh' Web Lock (cross-tab mutex against a
    // concurrent silent refresh), while the (already-completed) network call is
    // outside it — Web Locks are not reentrant.
    async finishWithToken(tokenInfo: dynamicObj, pending: MfaPending) {
      const auth_token_store = useAuthTokenStore();
      const applyWrite = async () => {
        auth_token_store.setTokenInLocalStorage(tokenInfo);
        await auth_token_store.setAuthToken(tokenInfo.access_token);
        if (tokenInfo.org_id) {
          SessionStorage.set('active_org_id', String(tokenInfo.org_id));
        }
      };
      const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined;
      if (locks && typeof locks.request === 'function') {
        await locks.request('docbits-token-refresh', applyWrite);
      } else {
        await applyWrite();
      }

      AppVersion.updateVersion();
      LocalStorage.remove('selectedSubOrg');
      LocalStorage.remove('intentional_logout');

      const redirectUrl = pending.redirect
        ? `/prepare-dashboard?redirect=${pending.redirect}`
        : '/prepare-dashboard';
      if (pending.forceFullReload) {
        window.location.href = redirectUrl;
        return;
      }
      this.$router.push(redirectUrl);
    },
  },
});
</script>
